import{_ as i,l as o,o as e,c as s,v as t,p as l,x as r,d as E,i as c,S as m}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"费用滑点蒙特卡洛","description":"","frontmatter":{"title":"费用滑点蒙特卡洛","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cost-mc-sensitivity.md","filePath":"quant/cost-mc-sensitivity.md","lastUpdated":1789023840000}'),d={name:"quant/cost-mc-sensitivity.md"};function h(p,a,u,B,A,C){const n=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="费用滑点蒙特卡洛" tabindex="-1">费用滑点蒙特卡洛 <a class="header-anchor" href="#费用滑点蒙特卡洛" aria-label="Permalink to &quot;费用滑点蒙特卡洛&quot;">​</a></h1><div class="epigraph"><p>许多异常按换手排序后，高换手一端在交易成本上不可交易；结论随价差与冲击假设而翻转，说明「扣费后仍显著」必须做成对成本参数的函数，而不是做成一个点。</p><footer>—— Novy-Marx and Velikov, Review of Financial Studies, 2016；对照 Perold, Journal of Portfolio Management, 1988</footer></div><p><a href="/quant/cost-sensitivity">费用敏感性</a> 用网格扫价差乘数与冲击系数，画出 \\(\\mathrm{SR}_{\\mathrm{net}}(c)\\) 和保本成本 \\(c^\\star\\)。网格假定每个 \\(c\\) 都是已知常数。真实成本是一组不确定的参数：有效价差、<a href="/quant/sqrt-impact">平方根冲击</a>的系数、借券费率、成交率、时机误差，彼此相关，且随波动与拥挤变。蒙特卡洛把 \\(c\\) 写成分布，把净业绩写成该分布下的随机量：不是「我们扣了 8 个基点」，而是「在成本先验下，净边缘为正的概率、以及翻转点落在观测价差的哪一段」。它与<a href="/quant/tca">成交后分析</a>互补：TCA 校准分布的位置，MC 传播校准误差。Hou–Xue–Zhang 复制时经济幅度已经变小，成本先验稍往上移，许多「加权后仍显著」的异常会过零；McLean–Pontiff 的发表后剩余收益同样要在成本分布里重新过零，而不是点估计过零一次就算数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>净收益 \\(\\mu_{\\mathrm{net}}=\\mu_0-\\tilde{c}\\cdot\\mathrm{TO}\\)，其中 \\(\\tilde{c}\\) 是单位换手的随机成本。\\(\\tilde{c}\\) 至少含：半价差或有效价差、临时冲击、永久冲击、借券、税费、未成交的机会成本。把它们压成常数，等于假设一个与名字、波动、参与率无关的世界。对该世界里的夏普做<a href="/quant/deflated-sharpe">Deflated Sharpe</a>，统计量再干净，输入也是错的。</p><p>更麻烦的是参数相关。波动上升时价差与冲击系数往往一起变大，换手也可能上升；拥挤时永久冲击比例上升，借券费跳升。网格把各轴独立扫一遍，会低估「坏成本同时发生」的尾部。MC 用联合分布——经验上可用历史有效价差、短fall、借券时间序列的自助法或参数 copula——才能看到净边缘的左尾。高换手策略对这个左尾最敏感：Novy-Marx–Velikov 按换手分档之后，高换手一端在成本假设上不可交易，结论随模型翻转。</p><h3 id="实施缺口的每一项都是一个随机源" tabindex="-1">实施缺口的每一项都是一个随机源 <a class="header-anchor" href="#实施缺口的每一项都是一个随机源" aria-label="Permalink to &quot;实施缺口的每一项都是一个随机源&quot;">​</a></h3><p>Perold 的实施缺口是决策价到最终成交的全程差异。滑点常被回测写成「相对下一根 bar 偏了若干 tick」。前者是账户诊断，后者是模拟器参数。MC 应分别冲击：价差乘数、冲击函数系数、成交率、延误、借券。只扰动一个「总费用 bp」，会把延误与冲击的协方差藏掉。身份也要进分布：Frazzini–Israel–Moskowitz 的机构短fall 低于许多学术价差模型；用他们的点估计当唯一 \\(c\\)，再声称零售可复制的日频策略「对成本不敏感」，是身份错配。MC 的每一列先验都要注明：谁的成本、哪一段样本估出来的。</p><p><span class="marginnote">只对最终冠军做一次成本 MC，是虚假稳健。冠军是在某一种 \\(c\\) 下选出来的。应在每次 MC 抽样里重新选择，或至少对候选集合同时评分，让选择程序本身对 \\(c\\) 的分布稳健。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>先验。</strong> 价差：用历史有效价差的截面分位或按 ADV、波动分层的回归残差，做成对数正态或经验分布。冲击系数：用自己成交回报校准平方根或线性核，参数给标准误，MC 从渐近正态或自助法抽。借券：对空头腿用费率的历史路径重抽样，危机月单独加一层膨胀。成交率：对涨跌停、浅簿名字用 Beta 分布，均值取模拟器完成率。相关：至少让价差与冲击系数正相关，让换手与波动正相关。</p><p><strong>目标量。</strong> 每次抽样计算：扣费后夏普、\\(\\mu_{\\mathrm{net}}\\)、\\(c^\\star\\) 是否低于该次抽样的实现成本、最大回撤、以及 \\(\\mu_{\\mathrm{net}}(A)\\) 过零的规模。报告这些量的中位数、10% 分位、以及「净边缘 \\(\\gt 0\\)」的频率。对统计套利还应按 ADV 分位分层抽，避免用指数期货的窄先验给小盘策略背书。成本参数在训练段估计、在检验段冻结后再做 MC，否则用全样本价差解释全样本信号，又是一层<a href="/quant/cv-leakage-finance">泄漏</a>。</p><p><strong>与选择的联合。</strong> 对每一组超参计算一条 \\(c\\mapsto\\mathrm{SR}_{\\mathrm{net}}(c)\\)，在 MC 样本上取最差 10% 或期望作为选择标准。另一种做法是把成本情景嵌进 <a href="/quant/cpcv">CPCV</a> 路径：过拟合概率应在坏成本下仍然不是二分之一。回测引擎必须把费用、税费、借券与滑点写成可配置输入，否则 MC 每次都要改代码，实际上不会做。</p><h3 id="保本成本的分布比一个-难作假" tabindex="-1">保本成本的分布比一个 \\(c^\\star\\) 难作假 <a class="header-anchor" href="#保本成本的分布比一个-难作假" aria-label="Permalink to &quot;保本成本的分布比一个 $c^\\star$ 难作假&quot;">​</a></h3><p>点估计 \\(c^\\star\\) 使 \\(\\mu_{\\mathrm{net}}=0\\)。MC 给出 \\(c^\\star\\) 的分布，再与观测有效价差的分布比。若 \\(c^\\star\\) 的 10% 分位已经低于价差的 10% 分位，策略在观测成本下经常没有边缘；若 \\(c^\\star\\) 的下尾仍高于价差的上尾，结论对成本较不敏感。把这条比较按发表前后切开：McLean–Pontiff 的发表后毛收益更低，\\(c^\\star\\) 左移，许多原文「扣费后仍显著」会翻转。Hou–Xue–Zhang 的市值加权把 \\(\\mu_0\\) 本身削薄，同样左移 \\(c^\\star\\)。MC 要同时扰动毛收益的衰减情景与成本先验，否则只是在一个已经乐观的 \\(\\mu_0\\) 上撒成本噪声。</p><p><span class="marginnote">平方根系数的标准误往往被低估：校准样本是活下来的策略与当时选中的名字。MC 应把校准的选择偏差加成更厚的先验，而不是把回归标准误当成全部不确定性。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>成本进入期望的方式是乘换手，但换手本身对成本参数有弹性：价差变宽，阈值再平衡会少交易；冲击变贵，优化器会降换手。MC 若把换手冻在 \\(c=0\\) 的路径上，会高估成本的伤害，也会低估「高换手冠军在坏成本下会先被换掉」的选择效应。完整做法是每次抽样重跑带成本的目标函数，让换手内生。这比事后减常数贵，但对应的是真实决策。</p><p>永久冲击与临时冲击在 MC 里不应共用一个乘数。临时部分随参与率、当日深度变；永久部分随信息泄露与拥挤变。对容量曲线做 MC，扰动的是核 \\(G\\) 的半衰期与永久比例，见<a href="/quant/strategy-capacity-decay">策略容量与冲击衰减</a>。只扰动「滑点 bp」，会把存量容量问题误写成流量费用问题。</p><h3 id="经济显著性是-mc-左尾过零与否" tabindex="-1">经济显著性是 MC 左尾过零与否 <a class="header-anchor" href="#经济显著性是-mc-左尾过零与否" aria-label="Permalink to &quot;经济显著性是 MC 左尾过零与否&quot;">​</a></h3><p>统计显著的多空，在成本分布的左尾上可能没有经济显著。<a href="/quant/econ-vs-stat-sig">经济 vs 统计</a> 把门槛说清楚：t 高可以来自微盘等权、来自长样本的微弱溢价、来自未扣费。MC 是把「微弱溢价 × 不确定成本」变成可报告的概率。Harvey–Liu–Zhu 的 t&gt;3 管发现；成本 MC 管发现之后能不能付账。两道闸都要通过。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>历史价差不是未来成本。电子化之后有效价差系统性下降，用 1990 年代先验会过度惩罚；用最近三年最窄价差又会过度乐观。应至少做两种先验：保守（含危机分位）与基准（近期中位数），分别报告。A 股涨跌停使成交率的先验在板上坍缩到零，MC 必须允许「未成交」这一原子事件，而不是把滑点加到无穷。不要用危机期高 ADV 去收窄冲击系数的先验。</p><p>不要把 MC 当成可以把任意策略「做成稳健」的仪式。若 90% 的抽样净边缘为负，结论是策略不可交易，而不是再抽一次直到频率好看。参数先验的支撑必须预先指定；看到结果后改分布，是另一层过拟合。</p><p><span class="marginnote">出处：Novy-Marx and Velikov, <em>RFS</em>, 2016；Perold, <em>JPM</em>, 1988；Keim and Madhavan, <em>FAJ</em>, 1998；Korajczyk and Sadka, <em>JFE</em>, 2004；McLean and Pontiff, <em>JF</em>, 2016；Hou, Xue and Zhang, <em>RFS</em>, 2020。冲击函数见 Almgren–Chriss；身份错配见 Frazzini, Israel and Moskowitz 的执行短fall 讨论。</span></p>',25)),(e(),l(m,null,{default:r(()=>[c(n,{id:"mermaid-73",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRIOR%5B%22%E6%88%90%E6%9C%AC%E5%85%88%E9%AA%8C%EF%BC%9A%E4%BB%B7%E5%B7%AE%20%2F%20%E5%86%B2%E5%87%BB%20%2F%20%E5%80%9F%E5%88%B8%20%2F%20%E6%88%90%E4%BA%A4%E7%8E%87%22%5D%20--%3E%20DRAW%5B%22%E8%81%94%E5%90%88%E6%8A%BD%E6%A0%B7%22%5D%0A%20%20MU0%5B%22%E6%AF%9B%E6%94%B6%E7%9B%8A%20%CE%BC_0%20%C2%B7%20%E5%8F%91%E8%A1%A8%E5%90%8E%E6%8A%98%E6%89%A3%22%5D%20--%3E%20NET%5B%22%CE%BC_net%5E(b)%22%5D%0A%20%20DRAW%20--%3E%20NET%0A%20%20TO%5B%22%E6%8D%A2%E6%89%8B%E5%86%85%E7%94%9F%E6%88%96%E5%86%BB%E7%BB%93%22%5D%20--%3E%20NET%0A%20%20NET%20--%3E%20DIST%5B%22%E5%87%80%E8%BE%B9%E7%BC%98%E5%88%86%E5%B8%83%22%5D%0A%20%20DIST%20--%3E%20P%5B%22P(%CE%BC_net%3E0)%22%5D%0A%20%20DIST%20--%3E%20CST%5B%22c*%20%E5%88%86%E4%BD%8D%20vs%20%E8%A7%82%E6%B5%8B%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20P%20--%3E%20GATE%7B%22%E5%B7%A6%E5%B0%BE%E8%BF%87%E9%9B%B6%3F%22%7D%0A%20%20CST%20--%3E%20GATE%0A%20%20GATE%20--%3E%7C%E5%90%A6%7C%20Z%5B%22%E4%B8%8D%E5%8F%AF%E4%BA%A4%E6%98%93%22%5D%0A%20%20GATE%20--%3E%7C%E6%98%AF%7C%20SEL%5B%22%E5%9C%A8%E5%88%86%E5%B8%83%E4%B8%8A%E9%80%89%E6%8B%A9%E8%B6%85%E5%8F%82%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>费用滑点蒙特卡洛把成本参数写成联合分布，报告净边缘为正的概率与 \\(c^\\star\\) 相对观测价差的位置，而不是一个扣费点。</li><li>高换手策略对成本左尾最敏感；独立网格会低估坏成本同时发生。</li><li>选择必须在抽样内重做或对成本分布稳健，只对冠军扫一遍是虚假稳健。</li><li>毛收益应叠加 McLean–Pontiff / Hou–Xue–Zhang 的衰减与加权缩水，再扰动成本。</li><li>先验要声明身份与样本；涨跌停下成交率必须允许未成交。</li><li>出处：Novy-Marx–Velikov, <em>RFS</em>, 2016；Perold, <em>JPM</em>, 1988；McLean–Pontiff, <em>JF</em>, 2016；Hou–Xue–Zhang, <em>RFS</em>, 2020。</li></ul>',2))])}const M=i(d,[["render",h]]);export{_ as __pageData,M as default};
